"""Mail (generated by Shikshya, PX.302). With EMAIL_HOST set, mail goes out by SMTP; without it a dev run prints
mail to the console and a production run sends none and says so once at start (settings.py, MAIL_ON). A mail is
sent only after the database commit that caused it, and a send that fails never fails the request. Logs name the
kind of mail and the error type, never an address or a link. NOTICES, from the plan, say which rows mail whom."""
import logging

from django.apps import apps
from django.conf import settings
from django.core.mail import send_mail
from django.db import transaction
from django.db.models.signals import post_save, pre_save
from django.utils import timezone

logger = logging.getLogger(__name__)
APP_NAME = 'cedar_patient_portal_779'
SUBJECTS = {
    'verify_email': 'Confirm your email for {app}',
    'booking_confirmed': 'Your {what} is confirmed',
    'order_paid': 'Payment received for order {number}',
}
BODIES = {
    'verify_email': ('Hello {name},\n\nPlease confirm your email address for {app}:\n{link}\n\n'
                     'The link works once and lasts 24 hours. If you did not sign up, you can ignore this '
                     'email.\n'),
    'booking_confirmed': 'Hello {name},\n\nYour {what}{when} is confirmed.\n\n{app}\n',
    'order_paid': ('Hello {name},\n\nWe received your payment for order {number}{amount}. Thank you.'
                   '\n\n{app}\n'),
}
# When a row of the model moves to one of the values, the people its links name get the mail.
NOTICES = [{'model': 'Order', 'status': 'status', 'values': ['received'], 'kind': 'order_paid', 'people': ['user'], 'what': 'order', 'when': '', 'amount': 'total_amount'}, {'model': 'Appointment', 'status': 'status', 'values': ['booked'], 'kind': 'booking_confirmed', 'people': ['patient', 'booked_by'], 'what': 'appointment', 'when': 'start_time', 'amount': ''}]
CONNECTED = False


def mail_on():
    """True when the app has a mail server (EMAIL_HOST): email verification (PX.303) runs only then."""
    return bool(getattr(settings, 'MAIL_ON', False))


def send(kind, user, **values):
    """Send one mail to a user after the current transaction commits; False when there is no address."""
    address = (getattr(user, 'email', '') or '').strip()
    if not address or kind not in SUBJECTS:
        return False
    name = getattr(user, 'first_name', '') or getattr(user, 'username', '') or 'there'
    values = dict(values, app=APP_NAME, name=name)
    subject = ' '.join(SUBJECTS[kind].format(**values).split())
    body = BODIES[kind].format(**values)

    def deliver():
        try:
            send_mail(subject, body, None, [address])
        except Exception as error:
            logger.warning('[Mail] %s not sent: %s', kind, type(error).__name__)

    transaction.on_commit(deliver)
    return True


def _when(row, field):
    value = getattr(row, field, None) if field else None
    if value is None:
        return ''
    if hasattr(value, 'hour'):
        value = timezone.localtime(value) if timezone.is_aware(value) else value
        return ' on ' + value.strftime('%d %b %Y at %H:%M')
    return ' on ' + value.strftime('%d %b %Y')


def _notice(sender):
    return next((n for n in NOTICES if n['model'] == sender.__name__), None)


def _remember(sender, instance, raw=False, **kwargs):
    """The status the row had before this save, read from the database."""
    notice = _notice(sender)
    if raw or notice is None or instance.pk is None:
        return
    rows = sender._default_manager.filter(pk=instance.pk).values_list(notice['status'], flat=True)
    instance._mail_status = rows.first()


def _notify(sender, instance, created=False, raw=False, **kwargs):
    """A row that has just reached a notice value mails the people its links name; a seed load mails no one."""
    notice = _notice(sender)
    if raw or notice is None:
        return
    now = getattr(instance, notice['status'], None)
    if now not in notice['values'] or (not created and getattr(instance, '_mail_status', None) == now):
        return
    amount = getattr(instance, notice['amount'], None) if notice['amount'] else None
    values = {'what': notice['what'], 'number': instance.pk, 'when': _when(instance, notice['when']),
              'amount': '' if amount is None else ' (%s)' % amount}
    for link in notice['people']:
        person = getattr(instance, link, None)
        if person is not None:
            send(notice['kind'], person, **values)


def connect():
    """Called once from ApiConfig.ready: the notices' signals, and a warning when the app has no mail server."""
    global CONNECTED
    for notice in NOTICES:
        try:
            model = apps.get_model('api', notice['model'])
        except LookupError:
            continue
        pre_save.connect(_remember, sender=model, dispatch_uid='mail-before-' + notice['model'])
        post_save.connect(_notify, sender=model, dispatch_uid='mail-after-' + notice['model'])
    CONNECTED = True
    if not mail_on() and not getattr(settings, 'DEBUG', False):
        logger.warning('[Mail] EMAIL_HOST is not set: this app sends no mail and email verification is off')
